size_t GetEngineStackSize() {
  const char* value = std::getenv("MOCKTAIL_ENGINE_STACK_MB");
  if (value == nullptr || value[0] == '\0') {
    return kDefaultEngineStackSize;
  }

  char* end = nullptr;
  unsigned long long stack_mb = std::strtoull(value, &end, 10);
  if (end == value || stack_mb == 0) {
    return kDefaultEngineStackSize;
  }

  size_t stack_size = static_cast<size_t>(stack_mb) * 1024 * 1024;
  return stack_size < kMinEngineStackSize ? kMinEngineStackSize : stack_size;
}

void PrintStage(int stage, const char* description) {
  g_current_stage = stage;
  if (stage != 5) {
    g_stage5_last_fallback_rip = 0;
  }
  std::cout << "[stage " << stage << "] " << description << '\n'
            << std::flush;
}

void PrintBacktraceNoSig(const char* prefix) {
  void* frames[64];
  int frame_count = backtrace(frames, 64);
  if (frame_count <= 0) {
    return;
  }

  char** symbols = backtrace_symbols(frames, frame_count);
  if (!symbols) {
    return;
  }

  write(2, prefix, std::strlen(prefix));
  for (int i = 0; i < frame_count; ++i) {
    size_t written = 0;
    if (symbols[i] != nullptr) {
      written = std::strlen(symbols[i]);
      write(2, symbols[i], written);
    }
    if (i + 1 < frame_count) {
      write(2, "\n", 1);
    }
  }
  write(2, "\n", 1);
  free(symbols);
}

bool IsReadableMemoryRange(uintptr_t address, size_t size) {
  if (address == 0 || size == 0 || address + size < address) {
    return false;
  }

  int fd = open("/proc/self/maps", O_RDONLY | O_CLOEXEC);
  if (fd < 0) {
    return false;
  }

  char buffer[262144];
  ssize_t bytes = 0;
  while (static_cast<size_t>(bytes) < sizeof(buffer) - 1) {
    ssize_t chunk =
        read(fd, buffer + bytes, sizeof(buffer) - 1 - bytes);
    if (chunk < 0) {
      if (errno == EINTR) {
        continue;
      }
      close(fd);
      return false;
    }
    if (chunk == 0) {
      break;
    }
    bytes += chunk;
  }
  close(fd);
  if (bytes <= 0) {
    return false;
  }
  buffer[bytes] = '\0';

  const char* line = buffer;
  while (*line != '\0') {
    const char* line_end = std::strchr(line, '\n');
    if (line_end == nullptr) {
      line_end = buffer + bytes;
    }

    const char* dash = static_cast<const char*>(
        std::memchr(line, '-', static_cast<size_t>(line_end - line)));
    const char* space = static_cast<const char*>(
        std::memchr(line, ' ', static_cast<size_t>(line_end - line)));
    if (dash == nullptr || space == nullptr || space + 1 >= line_end ||
        space[1] != 'r') {
      line = (*line_end == '\n') ? line_end + 1 : line_end;
      continue;
    }

    char* endptr = nullptr;
    uintptr_t start =
        static_cast<uintptr_t>(std::strtoull(line, &endptr, 16));
    if (endptr == nullptr || endptr != dash) {
      line = (*line_end == '\n') ? line_end + 1 : line_end;
      continue;
    }

    endptr = nullptr;
    uintptr_t end =
        static_cast<uintptr_t>(std::strtoull(dash + 1, &endptr, 16));
    if (endptr == nullptr || endptr != space || end <= start) {
      line = (*line_end == '\n') ? line_end + 1 : line_end;
      continue;
    }

    if (address >= start && address + size <= end) {
      return true;
    }

    line = (*line_end == '\n') ? line_end + 1 : line_end;
  }
  return false;
}

bool IsExecutableMemoryRange(uintptr_t address, size_t size) {
  if (address == 0 || size == 0 || address + size < address) {
    return false;
  }

  int fd = open("/proc/self/maps", O_RDONLY | O_CLOEXEC);
  if (fd < 0) {
    return false;
  }

  char buffer[262144];
  ssize_t bytes = 0;
  while (static_cast<size_t>(bytes) < sizeof(buffer) - 1) {
    ssize_t chunk =
        read(fd, buffer + bytes, sizeof(buffer) - 1 - bytes);
    if (chunk < 0) {
      if (errno == EINTR) {
        continue;
      }
      close(fd);
      return false;
    }
    if (chunk == 0) {
      break;
    }
    bytes += chunk;
  }
  close(fd);
  if (bytes <= 0) {
    return false;
  }
  buffer[bytes] = '\0';

  const char* line = buffer;
  while (*line != '\0') {
    const char* line_end = std::strchr(line, '\n');
    if (line_end == nullptr) {
      line_end = buffer + bytes;
    }

    const char* dash = static_cast<const char*>(
        std::memchr(line, '-', static_cast<size_t>(line_end - line)));
    const char* space = static_cast<const char*>(
        std::memchr(line, ' ', static_cast<size_t>(line_end - line)));
    if (dash == nullptr || space == nullptr || space + 3 >= line_end ||
        space[3] != 'x') {
      line = (*line_end == '\n') ? line_end + 1 : line_end;
      continue;
    }

    char* endptr = nullptr;
    uintptr_t start =
        static_cast<uintptr_t>(std::strtoull(line, &endptr, 16));
    if (endptr == nullptr || endptr != dash) {
      line = (*line_end == '\n') ? line_end + 1 : line_end;
      continue;
    }

    endptr = nullptr;
    uintptr_t end =
        static_cast<uintptr_t>(std::strtoull(dash + 1, &endptr, 16));
    if (endptr == nullptr || endptr != space || end <= start) {
      line = (*line_end == '\n') ? line_end + 1 : line_end;
      continue;
    }

    if (address >= start && address + size <= end) {
      return true;
    }

    line = (*line_end == '\n') ? line_end + 1 : line_end;
  }
  return false;
}

uintptr_t ReadPointerIfReadable(uintptr_t address) {
  if (!IsReadableMemoryRange(address, sizeof(uintptr_t))) {
    return 0;
  }
  return *reinterpret_cast<const uintptr_t*>(address);
}

uint32_t ReadU32IfReadable(uintptr_t address) {
  if (!IsReadableMemoryRange(address, sizeof(uint32_t))) {
    return 0;
  }
  return *reinterpret_cast<const uint32_t*>(address);
}

unsigned long long ReadVectorElementCountIfReadable(uintptr_t vector_address,
                                                    uintptr_t element_size) {
  if (element_size == 0 || !IsReadableMemoryRange(vector_address, 0x10)) {
    return 0;
  }
  const uintptr_t begin = ReadPointerIfReadable(vector_address);
  const uintptr_t end = ReadPointerIfReadable(vector_address + 0x08);
  if (begin == 0 || end < begin) {
    return 0;
  }
  return static_cast<unsigned long long>((end - begin) / element_size);
}

void ReadLibcxxStringPreview(uintptr_t address, char* out, size_t out_size) {
  if (out == nullptr || out_size == 0) {
    return;
  }
  out[0] = '\0';
  if (!IsReadableMemoryRange(address, 24)) {
    return;
  }

  unsigned char data[24];
  std::memcpy(data, reinterpret_cast<const void*>(address), sizeof(data));
  const bool is_long = (data[0] & 1u) != 0;
  size_t length = 0;
  uintptr_t chars = 0;
  if (is_long) {
    auto* words = reinterpret_cast<const uintptr_t*>(data);
    length = static_cast<size_t>(words[1]);
    chars = words[2];
  } else {
    length = data[0] >> 1;
    chars = address + 1;
  }
  if (length == 0 || length >= 4096 || chars == 0 ||
      !IsReadableMemoryRange(chars, length)) {
    return;
  }

  const size_t copy_length = std::min(length, out_size - 1);
  std::memcpy(out, reinterpret_cast<const void*>(chars), copy_length);
  for (size_t i = 0; i < copy_length; ++i) {
    const unsigned char c = static_cast<unsigned char>(out[i]);
    if (c < 0x20 || c > 0x7e) {
      out[i] = '.';
    }
  }
  out[copy_length] = '\0';
}

bool ReadLibcxxStringView(uintptr_t address,
                          const char** chars_out,
                          size_t* length_out) {
  if (chars_out == nullptr || length_out == nullptr) {
    return false;
  }
  *chars_out = nullptr;
  *length_out = 0;
  if (!IsReadableMemoryRange(address, 24)) {
    return false;
  }

  unsigned char data[24];
  std::memcpy(data, reinterpret_cast<const void*>(address), sizeof(data));
  const bool is_long = (data[0] & 1u) != 0;
  size_t length = 0;
  uintptr_t chars = 0;
  if (is_long) {
    auto* words = reinterpret_cast<const uintptr_t*>(data);
    length = static_cast<size_t>(words[1]);
    chars = words[2];
  } else {
    length = data[0] >> 1;
    chars = address + 1;
  }
  if (length == 0 || length >= 4096 || chars == 0 ||
      !IsReadableMemoryRange(chars, length)) {
    return false;
  }

  *chars_out = reinterpret_cast<const char*>(chars);
  *length_out = length;
  return true;
}

void ReadMemoryHexPreview(uintptr_t address, char* out, size_t out_size) {
  if (out == nullptr || out_size == 0) {
    return;
  }
  out[0] = '\0';
  if (address == 0) {
    std::snprintf(out, out_size, "null");
    return;
  }

  constexpr size_t kMaxPreviewBytes = 24;
  unsigned char bytes[kMaxPreviewBytes];
  size_t byte_count = 0;
  while (byte_count < kMaxPreviewBytes &&
         IsReadableMemoryRange(address + byte_count, 1)) {
    bytes[byte_count] =
        *reinterpret_cast<const unsigned char*>(address + byte_count);
    ++byte_count;
  }
  if (byte_count == 0) {
    std::snprintf(out, out_size, "unreadable");
    return;
  }

  char hex[kMaxPreviewBytes * 3 + 1];
  char ascii[kMaxPreviewBytes + 1];
  size_t hex_pos = 0;
  for (size_t i = 0; i < byte_count && hex_pos < sizeof(hex); ++i) {
    const int written =
        std::snprintf(hex + hex_pos, sizeof(hex) - hex_pos, "%02x%s",
                      bytes[i], i + 1 == byte_count ? "" : " ");
    if (written <= 0) {
      break;
    }
    hex_pos += static_cast<size_t>(written);
    ascii[i] = bytes[i] >= 0x20 && bytes[i] <= 0x7e
                   ? static_cast<char>(bytes[i])
                   : '.';
  }
  hex[std::min(hex_pos, sizeof(hex) - 1)] = '\0';
  ascii[byte_count] = '\0';
  std::snprintf(out, out_size, "%s |%s|", hex, ascii);
}

void ReadRawStringPreview(uintptr_t address, size_t length, char* out,
                          size_t out_size) {
  if (out == nullptr || out_size == 0) {
    return;
  }
  out[0] = '\0';
  if (address == 0 || length == 0) {
    return;
  }

  const size_t copy_length = std::min(length, out_size - 1);
  if (!IsReadableMemoryRange(address, copy_length)) {
    std::snprintf(out, out_size, "unreadable");
    return;
  }

  const auto* bytes = reinterpret_cast<const unsigned char*>(address);
  for (size_t i = 0; i < copy_length; ++i) {
    out[i] = std::isprint(bytes[i]) ? static_cast<char>(bytes[i]) : '.';
  }
  out[copy_length] = '\0';
}

void ReadCStringPreview(uintptr_t address, char* out, size_t out_size) {
  if (out == nullptr || out_size == 0) {
    return;
  }
  out[0] = '\0';
  if (address == 0) {
    return;
  }

  size_t length = 0;
  while (length + 1 < out_size &&
         IsReadableMemoryRange(address + length, 1)) {
    const unsigned char byte =
        *reinterpret_cast<const unsigned char*>(address + length);
    if (byte == '\0') {
      break;
    }
    out[length] = std::isprint(byte) ? static_cast<char>(byte) : '.';
    ++length;
  }
  out[length] = '\0';
  if (length == 0 && !IsReadableMemoryRange(address, 1)) {
    std::snprintf(out, out_size, "unreadable");
  }
}

